def paires(xs, ys):
    if len(xs) != len(ys):
        raise ValueError("les deux séries doivent avoir la même longueur")
    return [[x, y] for x, y in zip(xs, ys)]

def covariance(xs, ys):
    mx = sum(xs) / len(xs)
    my = sum(ys) / len(ys)
    return round(sum((x - mx) * (y - my) for x, y in zip(xs, ys)) / len(xs), 2)

