def covariance(xs, ys):
    mx = sum(xs) / len(xs)
    my = sum(ys) / len(ys)
    return round(sum((x - mx) * (y - my) for x, y in zip(xs, ys)) / len(xs), 2)

def sens(xs, ys):
    if len(xs) != len(ys):
        raise ValueError("longueurs différentes")
    mx = sum(xs) / len(xs)
    my = sum(ys) / len(ys)
    cov = sum((x - mx) * (y - my) for x, y in zip(xs, ys)) / len(xs)
    if abs(cov) < 0.01:
        return "aucune"
    return "croissante" if cov > 0 else "décroissante"
